function strip(html: string) {
  return html.replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ")
    .replace(/<!--[\s\S]*?-->/g," ").replace(/<[^>]+>/g,"\n")
    .replace(/&nbsp;/g," ").replace(/&amp;/g,"&").replace(/&#8217;/g,"'").replace(/&#8211;/g,"-").replace(/&#8220;|&#8221;/g,'"')
    .split("\n").map(s=>s.trim()).filter(Boolean).join("\n");
}
async function f(u: string) { try { const r = await tools.web_fetch({ url: u }); return strip(r.body.content||""); } catch(e){ return "ERR "+String(e).slice(0,120); } }

const [mk, cn] = await Promise.all([
  f("https://dshmarketplace.dev/zh/plugins?category=model&page=1"),
  f("https://www.cnblogs.com/jason-chen-11/p/22585390"),
]);
// extract name/author/star triples from marketplace
const lines = mk.split("\n");
const out: string[] = [];
for (let i=0;i<lines.length;i++){
  if (/^\d+(\.\d+)?k?$/.test(lines[i]) && i>=1) {
    out.push(`${lines[i-1]} | ${lines[i-2] ?? ""} | ${lines[i]}`);
  }
}
